def min_days(bloom_day, m, k):
    n = len(bloom_day)
    if m * k > n:
        return -1

    def bouquets_by_day(day):
        total, run = 0, 0
        for b in bloom_day:
            if b <= day:
                run += 1
                if run == k:
                    total += 1
                    run = 0
            else:
                run = 0
        return total

    lo, hi = min(bloom_day), max(bloom_day)

    while lo < hi:
        mid = (lo + hi) // 2
        if bouquets_by_day(mid) >= m:
            hi = mid
        else:
            lo = mid + 1

    return lo

